// Notion DBから取得したTodoを整形
const todos = $input.all();

if (todos.length === 0) {
  return [
    {
      json: {
        message: "未着手のTodoはありません",
        count: 0,
        todos: []
      }
    }
  ];
}

// Todoを整形
const formattedTodos = todos.map(item => {
  const properties = item.json.properties;

  return {
    title: properties.Name?.title?.[0]?.plain_text || '(タイトルなし)',
    status: properties.Status?.select?.name || '',
    priority: properties.Priority?.select?.name || '',
    dueDate: properties['Due Date']?.date?.start || null,
    tags: properties.Tags?.multi_select?.map(t => t.name) || [],
    url: item.json.url
  };
});

return [
  {
    json: {
      message: `未着手のTodoが${formattedTodos.length}件あります`,
      count: formattedTodos.length,
      todos: formattedTodos
    }
  }
];

