={{ JSON.stringify({
  embeds: [{
    title: '📝 未着手のTodo一覧',
    description: $json.message,
    color: 3447003,
    fields: $json.todos.slice(0, 10).map(todo => ({
      name: todo.title,
      value: `優先度: ${todo.priority || 'なし'} | 期限: ${todo.dueDate || 'なし'}`,
      inline: false
    })),
    footer: { text: `全${$json.count}件のTodo` },
    timestamp: $now.toISO()
  }]
}) }}
